const e=$json.event||$json.body?.event||$json;
const user=String(e.user||e.message?.user||'').trim();
const channel=String(e.channel||e.item?.channel||'').trim();
let text=String(e.text||e.message?.text||'').trim().replace(/<@[A-Z0-9]+>/g,'').trim();
const allowedUsers=['REPLACE_SLACK_USER_ID'];
const allowedChannels=['REPLACE_SLACK_CHANNEL_ID'];
const authorized=allowedUsers.includes(user)&&allowedChannels.includes(channel)&&!e.bot_id&&!e.subtype;
let action=null;
if(authorized&&text.startsWith('!action ')){
  try{action=JSON.parse(text.slice(8).trim());}catch{throw new Error('Invalid !action JSON');}
  if(!action||typeof action!=='object'||!action.type||!action.payload)throw new Error('!action must be a JSON action object with type and payload');
  text=`Operator requested approved action ${action.type}`;
}
const request_id=`slack_${String($json.event_id||e.client_msg_id||e.ts||Date.now()).replace(/[^A-Za-z0-9._:-]/g,'_')}`;
return[{json:{authorized,user,channel,text,action,request_id,source:'slack'}}];

const r=$json; const src=$('Normalize Slack Command').item.json;
let text='';
if(r.status==='approval_required') text=`Approval required for ${r.request_id||src.request_id}\n${r.approval_url||''}`;
else text=r.summary_markdown||r.answer_markdown||r.draft||r.message||JSON.stringify(r);
if(text.length>3500) text=text.slice(0,3490)+'…';
return[{json:{channel:src.channel,text,response:r}}];
